BEGIN TRANSACTION;
CREATE TABLE budget(id TEXT PRIMARY KEY, reserved REAL NOT NULL,
                actual REAL, status TEXT NOT NULL);
CREATE TABLE edges(id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE events(seq INTEGER PRIMARY KEY, kind TEXT NOT NULL,
                payload TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE nodes(id TEXT PRIMARY KEY, type TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE snapshots(version INTEGER PRIMARY KEY, hash TEXT NOT NULL, body TEXT NOT NULL);
COMMIT;
